  assert.equal(tickSession(active, first.generation, MISMATCH_MS), active);
  const changed = replaceGame(first, createGame(boardCode(6, 1)), false);
  assert.equal(changed.preferences.size, 6);
});

test('changing a deal name preserves all active session data', () => {
  const started = activateSession(
    activateSession(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), 0),
    1,
  );
  const paused = { ...started, paused: true };
  const named = setGameName(paused, '  Café  ');
  assert.equal(named.game.name, '  Café  ');
  assert.deepEqual({ ...named, game: { ...named.game, name: '' } }, paused);
  assert.equal(setGameName(named, '').game.name, '');
  assert.equal(setGameName(named, 'x'.repeat(41)), named);
  assert.equal(setGameName(named, 'bad\nname'), named);
});

